'use strict';
Object.assign(navs,{overview:'Tổng quan',content:'Nội dung',calendar:'Lịch đăng',series:'Bộ truyện',publish:'Đăng bài',tracking:'Theo dõi',images:'Tạo ảnh',pinterest:'Pinterest',etsy:'Etsy',prompts:'Câu lệnh',metrics:'Doanh thu',channels:'Kênh',settings:'Cài đặt'});
// Reorder navigation around daily operations.
const navOrder=['overview','content','series','images','publish','pinterest','etsy','calendar','tracking','metrics','prompts','channels','settings'];const navCopy={...navs};Object.keys(navs).forEach(k=>delete navs[k]);navOrder.forEach(k=>navs[k]=navCopy[k]);
db.workflows??=[];db.assets??=[];
function ensureWorkflowData(){db.workflows??=[];db.assets??=[]}
const baseRender=render;render=function(){ensureWorkflowData();baseRender()};
const wfDialog=document.createElement('dialog');wfDialog.id='workflowEditor';wfDialog.innerHTML='<form id="workflowForm"><div class="dialog-head"><h2 id="workflowTitle"></h2><button type="button" data-wclose aria-label="Đóng cửa sổ">×</button></div><div id="workflowFields" class="workflow-fields"></div><div class="dialog-actions"><button type="button" data-wclose>Đóng</button><button type="button" id="wfDelete" class="danger">Xóa</button><span class="spacer"></span><button type="button" id="wfCopy">Sao chép gói nội dung</button><button type="submit" class="primary">Lưu</button></div></form>';document.body.append(wfDialog);
const confirmDialog=document.createElement('dialog');confirmDialog.innerHTML='<div class="dialog-head"><h2>Xác nhận thao tác</h2></div><p id="confirmMessage" style="padding:24px"></p><div class="dialog-actions"><button id="confirmNo">Hủy</button><button id="confirmYes" class="primary">Xác nhận</button></div>';document.body.append(confirmDialog);
function uiConfirm(text){return new Promise(resolve=>{$('#confirmMessage').textContent=text;confirmDialog.showModal();let done=v=>{confirmDialog.close();resolve(v)};$('#confirmNo').onclick=()=>done(false);$('#confirmYes').onclick=()=>done(true);confirmDialog.oncancel=e=>{e.preventDefault();done(false)}})}
function flowNotice(text){return `<div class="notice"><p>${text}</p></div>`}
function publishPage(){const items=db.content.filter(c=>['review','approved','live'].includes(c.status));return heading('Đăng bài','Duyệt, chuẩn bị gói nội dung và ghi nhận xuất bản.',addBtn('content','Tạo nội dung'))+flowNotice('Chế độ thủ công: duyệt bài trong Xưởng, sao chép nội dung, mở nền tảng để đăng, sau đó lưu link xác nhận. Chưa kết nối API tự đăng.')+`<div class="stats">${[['Chờ duyệt',items.filter(c=>c.status==='review').length],['Sẵn sàng đăng',items.filter(c=>c.status==='approved').length],['Đã đăng',items.filter(c=>c.status==='live').length],['Đã xếp lịch',items.filter(c=>c.scheduledAt&&c.status!=='live').length]].map(([l,n])=>`<div class="stat"><span>${l}</span><strong>${n}</strong></div>`).join('')}</div><section class="panel"><h2>Hàng đợi xuất bản</h2>${items.length?items.map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><small>${esc(channelName(c.channelId))} / ${dateText(c.scheduledAt)}</small></div><div class="actions">${badge(c)}<button data-pcopy="${c.id}">Sao chép bài</button>${safeLink(ch(c.channelId)?.link,'Mở kênh')}<button data-edit="content" data-id="${c.id}">${c.status==='review'?'Duyệt bài':c.status==='approved'?'Lưu link đã đăng':'Xem kết quả'}</button></div></div>`).join(''):empty('Chưa có bài trong hàng đợi','Tạo bài, nhập nội dung rồi chọn Chờ duyệt hoặc Đã duyệt.','<button data-go="content">Mở nội dung</button>')}</section>`}
function trackingPage(){let now=new Date;return heading('Theo dõi','Kiểm tra tiến độ, lịch trễ và kết quả sau xuất bản.',addBtn('metrics','Ghi số liệu'))+`<div class="grid two"><section class="panel"><h2>Chậm lịch</h2>${db.content.filter(c=>c.scheduledAt&&new Date(c.scheduledAt)<now&&c.status!=='live').map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><small>${dateText(c.scheduledAt)}</small></div><button data-edit="content" data-id="${c.id}">Xử lý</button></div>`).join('')||'<p class="muted mt">Không có bài trễ lịch.</p>'}</section><section class="panel"><h2>Kết quả theo kênh</h2>${db.channels.map(c=>`<div class="row"><div><strong>${esc(c.name)}</strong><small>${db.content.filter(x=>x.channelId===c.id&&x.status==='live').length} bài đã đăng / ${num(db.metrics.filter(x=>x.channelId===c.id).reduce((a,x)=>a+(x.views||0),0))} lượt xem đã ghi nhận</small></div>${safeLink(c.link,'Mở kênh')}</div>`).join('')||'<p class="muted mt">Thêm kênh để bắt đầu theo dõi.</p>'}</section></div><section class="panel mt"><h2>Nhật ký xuất bản</h2>${db.content.filter(c=>c.status==='live').map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><small>${esc(channelName(c.channelId))} / ${dateText(c.publishedAt)}</small></div>${safeLink(c.link,'Xem bài')}</div>`).join('')||'<p class="muted mt">Bài đã đăng và link xác nhận sẽ xuất hiện tại đây.</p>'}</section><section class="panel mt"><h2>Pinterest và Etsy</h2>${db.workflows.filter(w=>w.type==='pinterest'||w.type==='etsy').map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><small>${w.type==='etsy'?'Etsy':'Pinterest'} / ${w.status==='live'?'Đã đăng':w.status==='approved'?'Đã duyệt':'Nháp'}</small></div><button data-workflow="${w.type}" data-wid="${w.id}">Theo dõi</button></div>`).join('')||'<p class="muted mt">Chưa có ghim hoặc sản phẩm.</p>'}</section>`}
function workflowList(type){let rows=db.workflows.filter(w=>w.type===type);return rows.length?`<div class="cards">${rows.map(w=>`<article class="panel">${w.imageId?assetPreview(w.imageId):''}<span class="badge ${w.status==='live'?'live':w.status==='approved'?'approved':''}">${w.status==='live'?'Đã đăng':w.status==='approved'?'Đã duyệt':'Nháp'}</span><h2 class="mt">${esc(w.title)}</h2><p>${esc((w.description||'').slice(0,160))}</p><small>${type==='pinterest'?'Board: '+esc(w.board||'Chưa chọn'):'Giá: '+esc(w.price||'Chưa nhập')+' '+esc(w.currency||'USD')}</small><div class="actions"><button data-workflow="${type}" data-wid="${w.id}">Mở và xử lý</button>${safeLink(w.publishedUrl,'Xem trên nền tảng')}</div></article>`).join('')}</div>`:`<section class="panel">${empty(type==='pinterest'?'Chuẩn bị ghim đầu tiên':'Chuẩn bị sản phẩm đầu tiên',type==='pinterest'?'Chọn ảnh dọc, viết tiêu đề, mô tả và gắn link đích.':'Chuẩn bị ảnh, mô tả, giá và tag trước khi tạo listing.',`<button class="primary" data-workflow="${type}">+ ${type==='pinterest'?'Tạo ghim':'Tạo sản phẩm'}</button>`)}</section>`}
function pinterestPage(){return heading('Pinterest','Từ ảnh dọc đến ghim có link dẫn về nội dung của bạn.','<button class="primary" data-workflow="pinterest">+ Tạo ghim</button>')+flowNotice('Luồng: chuẩn bị ảnh 2:3 → viết tiêu đề, mô tả, board và link → duyệt → đăng thủ công → lưu link ghim. API Pinterest chưa kết nối.')+workflowList('pinterest')}
function etsyPage(){return heading('Etsy','Chuẩn bị sản phẩm, mô tả và bộ tag trong một màn hình.','<button class="primary" data-workflow="etsy">+ Tạo sản phẩm</button>')+flowNotice('Luồng: ảnh sản phẩm → tiêu đề, mô tả, giá và 13 tag → duyệt → tạo listing thủ công trên Etsy → lưu link sản phẩm. Chưa có kết nối tài khoản Etsy.')+workflowList('etsy')}
function assetPreview(id){const a=db.assets.find(a=>a.id===id);return a?.data?`<img class="asset-preview" src="${esc(a.data)}" alt="${esc(a.title)}">`:''}
function imagesPage(){return heading('Tạo ảnh','Soạn yêu cầu ảnh, nhận ảnh từ AI và quản lý ảnh cho từng bài.','<button class="primary" id="newAsset">+ Chuẩn bị ảnh</button>')+flowNotice('Hiện dùng AI thủ công: soạn và sao chép prompt → gửi vào ChatGPT/Claude → tải ảnh kết quả → nhập lại vào Xưởng. Chưa có tạo ảnh tự động trong web.')+`<div class="cards">${db.assets.map(a=>`<article class="panel">${a.data?`<img class="asset-preview" src="${esc(a.data)}" alt="${esc(a.title)}">`:'<div class="asset-empty">Chưa nhập ảnh kết quả</div>'}<h2>${esc(a.title)}</h2><small>${esc(a.ratio||'2:3')} / ${a.contentId?esc(db.content.find(c=>c.id===a.contentId)?.title||'Bài đã xóa'):'Ảnh độc lập'}</small><div class="actions"><button data-asset="${a.id}">Mở prompt / nhập ảnh</button>${a.data?`<button data-download-asset="${a.id}">Tải ảnh</button>`:''}</div></article>`).join('')}</div>${db.assets.length?'':`<section class="panel">${empty('Bắt đầu bằng yêu cầu hình ảnh','Lưu prompt và ảnh kết quả, rồi chọn lại trong Pinterest hoặc Etsy.','<button id="newAssetEmpty">Chuẩn bị ảnh đầu tiên</button>')}</section>`}`}
let wfType='',wfId='',assetDraft='',pendingWorkflow=null;
function wfValues(){return Object.fromEntries(new FormData($('#workflowForm')))}
function openWorkflow(type,id='',defaults={}){ensureWorkflowData();wfType=type;wfId=id;const o={...(type==='asset'?db.assets:db.workflows).find(w=>w.id===id),...defaults};assetDraft=o.data||'';$('#wfDelete').hidden=!id;$('#workflowTitle').textContent=type==='asset'?'Yêu cầu và kết quả ảnh':type==='pinterest'?'Chuẩn bị ghim Pinterest':'Chuẩn bị sản phẩm Etsy';let f='';if(type==='asset'){f=input('title','Tên ảnh',o.title,'text','required maxlength="200"')+select('contentId','Liên kết nội dung',[['','Ảnh độc lập'],...db.content.map(c=>[c.id,c.title])],o.contentId||'')+select('ratio','Tỷ lệ',['2:3','16:9','1:1','4:5'],o.ratio||'2:3')+input('prompt','Câu lệnh ảnh',o.prompt||'Create one standalone image. Subject: [describe the scene]. Style: [visual direction]. No watermark.','textarea','required')+`<div class="helper"><button type="button" id="buildAssetPrompt">Ghép ngữ cảnh từ bài viết</button><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Mở ChatGPT để tạo ảnh</a><p class="mt">Không gửi tự động. Sao chép prompt rồi tạo ảnh trong AI của bạn.</p></div><label class="field full">Nhập ảnh kết quả (JPG, PNG, WebP; tối đa 10 MB)<input type="file" id="assetFile" accept="image/jpeg,image/png,image/webp"></label><div id="assetPreviewArea" class="full">${assetDraft?`<img class="asset-preview" src="${esc(assetDraft)}" alt="Ảnh đã nhập">`:''}</div>`}else{f=input('title','Tiêu đề',o.title,'text',`required maxlength="${type==='etsy'?140:100}"`)+select('status','Trạng thái',[['draft','Nháp'],['approved','Đã duyệt'],['live','Đã đăng']],o.status||'draft')+select('imageId','Ảnh trong Xưởng',[['','Chưa chọn ảnh'],...db.assets.filter(a=>a.data).map(a=>[a.id,a.title])],o.imageId||'')+select('contentId','Nội dung liên quan',[['','Không liên kết'],...db.content.map(c=>[c.id,c.title])],o.contentId||'')+input('description','Mô tả',o.description,'textarea','required')+(type==='pinterest'?input('board','Tên board',o.board,'text','required')+input('destinationUrl','Link đích',o.destinationUrl,'url','required')+input('alt','Mô tả ảnh thay thế',o.alt):input('price','Giá sản phẩm',o.price,'number','min="0.01" step="0.01" required')+select('currency','Đơn vị tiền',['USD','EUR','GBP','VND'],o.currency||'USD')+select('productType','Loại sản phẩm',['Sản phẩm số','Sản phẩm vật lý'],o.productType||'Sản phẩm số')+input('tags','13 tag (phân cách bằng dấu phẩy)',o.tags,'textarea','required')+input('materials','Chất liệu / thông số thực tế',o.materials,'textarea'))+input('scheduledAt','Dự kiến đăng',o.scheduledAt,'datetime-local')+input('publishedUrl','Link đã đăng trên nền tảng',o.publishedUrl,'url')+`<div class="helper">Phải lưu Đã duyệt trước khi đánh dấu Đã đăng. Chỉ đánh dấu khi đã đăng thật và có link xác nhận. ${type==='etsy'?'Tag phải đủ 13, không trùng, mỗi tag tối đa 20 ký tự. Không dùng nhân vật hoặc thương hiệu chưa có quyền.':'Chọn ảnh dọc 2:3 cho ghim.'}</div>`+`<div class="helper actions"><button type="button" id="wfExport">Tải gói JSON</button>${safeLink(type==='etsy'?'https://www.etsy.com/your/shops/me/tools/listings/create':'https://www.pinterest.com/pin-builder/','Mở trang đăng '+(type==='etsy'?'Etsy':'Pinterest'))}<button type="button" id="wfPrepareAI">Soạn yêu cầu AI</button></div>`}$('#workflowFields').innerHTML=f;wfDialog.showModal()}
function workflowText(){const d=wfValues();return Object.entries(d).filter(([k,v])=>v).map(([k,v])=>k+': '+v).join('\n\n')}
$('#wfCopy').onclick=()=>copy(wfType==='asset'?wfValues().prompt:workflowText());
$('#workflowForm').onsubmit=e=>{e.preventDefault();const d=wfValues();for(const k in d)d[k]=d[k].trim();const old=(wfType==='asset'?db.assets:db.workflows).find(x=>x.id===wfId);if(wfType!=='asset'){if(d.status!=='draft'&&!d.imageId)return workflowError('Hãy chọn ảnh kết quả trước khi duyệt hoặc đăng.');if(wfType==='etsy'&&d.status!=='draft'){const tags=d.tags.split(',').map(x=>x.trim());if(tags.length!==13||tags.some(t=>!t||t.length>20)||new Set(tags.map(t=>t.toLowerCase())).size!==13)return workflowError('Cần đúng 13 tag khác nhau, mỗi tag từ 1 đến 20 ký tự.')}if(d.status==='live'&&(!old||!['approved','live'].includes(old.status)))return workflowError('Hãy lưu Đã duyệt trước, sau đó đăng và xác nhận.');if(d.status==='live'&&!d.publishedUrl)return workflowError('Nhập link đã đăng thật trên nền tảng.');if(d.publishedUrl){try{const u=new URL(d.publishedUrl);if(!['http:','https:'].includes(u.protocol)||!(wfType==='etsy'?/(^|\.)etsy\.com$/:/(^|\.)pinterest\.[a-z.]+$/).test(u.hostname))return workflowError('Link xác nhận phải thuộc '+(wfType==='etsy'?'etsy.com':'Pinterest'))}catch{return workflowError('Link không hợp lệ')}}}const before=JSON.stringify(db);const row={...old,...d,type:wfType,id:wfId||uid(),updatedAt:new Date().toISOString(),...(wfType==='asset'?{data:assetDraft}:{})};const key=wfType==='asset'?'assets':'workflows';if(wfId)db[key]=db[key].map(x=>x.id===wfId?row:x);else db[key].push(row);if(!save()){db=JSON.parse(before);return workflowError('Không lưu được. Bộ nhớ trình duyệt có thể đã đầy; hãy sao lưu.')}pendingWorkflow=null;$('#resumeWorkflow')?.remove();wfDialog.close();render();toast('Đã lưu '+(wfType==='asset'?'ảnh và prompt':'gói nội dung'))};
function workflowError(text){let p=$('#workflowError');if(!p){p=document.createElement('p');p.id='workflowError';p.className='helper error-text';$('#workflowFields').prepend(p)}p.textContent=text;p.scrollIntoView({block:'center'});p.setAttribute('role','alert')}
function closeWorkflow(){pendingWorkflow={type:wfType,id:wfId,values:wfValues(),data:assetDraft};wfDialog.close();toast('Đã đóng, có thể mở lại bản nháp.');let b=$('#resumeWorkflow');if(!b){b=document.createElement('button');b.id='resumeWorkflow';b.textContent='Mở lại bản nháp công việc';$('header').append(b)}b.onclick=()=>{if(pendingWorkflow)openWorkflow(pendingWorkflow.type,pendingWorkflow.id,{...pendingWorkflow.values,data:pendingWorkflow.data})}}
wfDialog.addEventListener('cancel',e=>{e.preventDefault();closeWorkflow()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-wclose'))closeWorkflow();if(b.dataset.workflow)openWorkflow(b.dataset.workflow,b.dataset.wid||'');if(b.dataset.asset)openWorkflow('asset',b.dataset.asset);if(['newAsset','newAssetEmpty'].includes(b.id))openWorkflow('asset');if(b.dataset.pcopy){const c=db.content.find(c=>c.id===b.dataset.pcopy);copy(c.title+'\n\n'+c.body)}if(b.dataset.downloadAsset){const a=db.assets.find(a=>a.id===b.dataset.downloadAsset);if(a?.data){const l=document.createElement('a');l.href=a.data;l.download='xuong-'+a.id+'.jpg';l.click()}}if(b.id==='wfExport')download('goi-'+wfType+'-'+today()+'.json',JSON.stringify(wfValues(),null,2),'application/json');if(b.id==='buildAssetPrompt'){const d=wfValues(),c=db.content.find(c=>c.id===d.contentId);$('#workflowFields [name="prompt"]').value=`Create exactly one standalone ${d.ratio} image. Translate the supplied scene context into English before interpreting.\nSubject: ${c?.title||d.title}\nContext: ${(c?.body||'Describe your scene here.').slice(0,3000)}\nVisual direction: ${ch(c?.channelId)?.visual||'Accurate setting, natural lighting.'}\nNo watermark, no collage, no unsupported events.`}if(b.id==='wfPrepareAI'){const d=wfValues();const text=wfType==='etsy'?`Viết mô tả Etsy cho sản phẩm ${d.title}. Thông số: ${d.materials||'chỉ dùng thông tin tôi cung cấp'}. Tạo đúng 13 tag tiếng Anh khác nhau, mỗi tag tối đa 20 ký tự. Không dùng thương hiệu của người khác.`:`Viết tiêu đề tối đa 100 ký tự, mô tả và alt text cho ghim Pinterest về ${d.title}. Link đích ${d.destinationUrl}. Board ${d.board}. Không bịa thông tin.`;copy(text)}});
document.addEventListener('change',async e=>{if(e.target.id!=='assetFile')return;const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)return workflowError('Chỉ nhận JPG/PNG/WebP dưới 10 MB.');try{const bitmap=await createImageBitmap(f),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);assetDraft=canvas.toDataURL('image/jpeg',.78);bitmap.close();$('#assetPreviewArea').innerHTML=`<img class="asset-preview" src="${assetDraft}" alt="Ảnh kết quả"><p class="muted">Ảnh lưu ${canvas.width} × ${canvas.height} px để tiết kiệm bộ nhớ. Giữ file gốc trên máy.</p>`}catch{workflowError('Không đọc được ảnh này. Hãy thử ảnh khác.')}});
view=navs[location.hash.slice(1)]?location.hash.slice(1):view;render();

$('#wfDelete').onclick=async()=>{if(wfType==='asset'&&db.workflows.some(w=>w.imageId===wfId))return workflowError('Ảnh đang dùng trong Pinterest hoặc Etsy. Hãy bỏ liên kết trước.');if(!await uiConfirm('Xóa mục công việc này? Thao tác không thể hoàn tác.'))return;const before=JSON.stringify(db),key=wfType==='asset'?'assets':'workflows';db[key]=db[key].filter(w=>w.id!==wfId);if(!save()){db=JSON.parse(before);return workflowError('Không lưu được thay đổi.')}pendingWorkflow=null;$('#resumeWorkflow')?.remove();wfDialog.close();render();toast('Đã xóa mục công việc')};
